        $path = $icons[$name] ?? '';
        if (empty($path)) return '<!-- icon: ' . $name . ' not found -->';

        $fill   = $variant === 'solid' ? 'currentColor' : 'none';
        $stroke = $variant === 'solid' ? 'none' : 'currentColor';
        $sw = $variant === 'solid' ? '' : ' stroke-width="1.5"';

        $px = 20;
        if (preg_match('/\bsize-(\d+(?:\.\d+)?)\b/', $class, $m)) {
            $px = (int) round((float) $m[1] * 4);
        }

        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" fill="%s" stroke="%s"%s viewBox="0 0 24 24" class="%s" width="%d" height="%d" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="%s" /></svg>',
            $fill, $stroke, $sw, $class, $px, $px, $path
        );
    }
